python3 -c "
import json
with open('/app/resources/treasury_bulletin_2013_12.json', 'r') as f:
    data = json.load(f)

# Look for individual income taxes in the data
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'individual' in str(k).lower() and 'income' in str(k).lower():
                print(f'Found key: {path}.{k}')
                print(f'Value: {v}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')

search(data)
"
